const downloadJson = (filename: string, value: unknown) => { const blob = new Blob([JSON.stringify(value, null, 2)], { type: "application/json" }); const url = URL.createObjectURL(blob); const anchor = document.createElement("a"); anchor.href = url; anchor.download = filename; anchor.click(); URL.revokeObjectURL(url); };
const downloadText = (filename: string, value: string) => { const blob = new Blob([value], { type: "text/plain;charset=utf-8" }); const url = URL.createObjectURL(blob); const anchor = document.createElement("a"); anchor.href = url; anchor.download = filename; anchor.click(); URL.revokeObjectURL(url); };

const flowStages = lookbookFlowStages;

const sampleItems: FloralItem[] = [
  { itemId: "TP-23109BS", name: "Berry Spray", colorFamily: "burgundy", structuralRole: "filler", emotionTags: ["warm", "festive"], status: "active", approved: true },
  { itemId: "TP-02672BH", name: "Ruscus Bush", colorFamily: "green", structuralRole: "greenery", emotionTags: ["structured"], status: "active", approved: true },
  { itemId: "TP-19907PT", name: "Wisteria Mini Pick", colorFamily: "lavender", structuralRole: "secondary", emotionTags: ["nostalgia"], status: "active", approved: true },
  { itemId: "TP-IVORY-ROSE", name: "Ivory Garden Rose", colorFamily: "ivory", structuralRole: "focal", emotionTags: ["resolution", "soft"], status: "active", approved: true },
];

export default function Workspace() {
  const { user, loading } = useAuth();
  const requestedProjectId = Number(new URLSearchParams(window.location.search).get("projectId"));
  const hasRequestedProject = isValidProjectId(requestedProjectId);
  const { data: currentProjectQuery } = trpc.memory.currentProject.useQuery(undefined, { enabled: Boolean(user) && !hasRequestedProject });
  const { data: routeProject } = trpc.memory.projectById.useQuery({ projectId: requestedProjectId }, { enabled: Boolean(user) && hasRequestedProject });
  const currentProject = routeProject ?? currentProjectQuery;
  const activeProjectId = isValidProjectId(currentProject?.id) ? currentProject.id : 0;
  const hasActiveProject = isValidProjectId(activeProjectId);
  const { data: inventory } = trpc.inventory.list.useQuery({ limit: 80, offset: 0 });
  const { data: capabilities } = trpc.billing.capabilities.useQuery();
  const fullStudioAccess = hasFullStudioAccess(user?.role, capabilities?.canUploadRender);
  const { data: ownedLookbooks } = trpc.lookbook.mine.useQuery();
  const currentLookbook = ownedLookbooks?.find((lookbook) => lookbook.projectId === activeProjectId) ?? null;
  const { data: savedDecisions } = trpc.floral.decisions.useQuery({ projectId: activeProjectId }, { enabled: activeProjectId > 0 });
  const { data: latestProfile } = trpc.memory.latestProfile.useQuery({ projectId: activeProjectId }, { enabled: activeProjectId > 0 });
  const { data: currentProfile } = trpc.memory.currentProfile.useQuery({ projectId: activeProjectId }, { enabled: activeProjectId > 0 });
  const { data: latestStory } = trpc.memory.latestStory.useQuery({ projectId: activeProjectId }, { enabled: activeProjectId > 0 });
  const { data: latestIntake } = trpc.memory.latestIntake.useQuery({ projectId: activeProjectId }, { enabled: activeProjectId > 0 });
  const utils = trpc.useUtils();
  const generateProfile = trpc.memory.generateProfile.useMutation({ onSuccess: () => { void utils.memory.latestProfile.invalidate(); void utils.memory.currentProfile.invalidate(); }, onError: (error) => window.alert(error.message) });
  const generateStory = trpc.memory.storyFromProfile.useMutation({ onSuccess: () => void utils.memory.latestStory.invalidate(), onError: (error) => window.alert(error.message) });
  const approveStory = trpc.memory.approveStory.useMutation({ onSuccess: () => void utils.memory.latestStory.invalidate(), onError: (error) => window.alert(error.message) });
  const [lookbookTitleDraft, setLookbookTitleDraft] = useState("");
  const lookbookUpdate = trpc.lookbook.update.useMutation({ onSuccess: () => void utils.lookbook.mine.invalidate() });
  const lookbookStatus = trpc.lookbook.setStatus.useMutation({ onSuccess: () => void utils.lookbook.mine.invalidate() });
  const lookbookShare = trpc.lookbook.generateShareLink.useMutation({ onSuccess: (result) => { void navigator.clipboard?.writeText(`${window.location.origin}${result.path}`); window.alert("Lookbook share link copied."); } });
  const ensureProject = trpc.memory.ensureProject.useMutation({ onSuccess: () => void utils.memory.currentProject.invalidate(), onError: (error) => window.alert(error.message) });
  const ensureLookbook = trpc.lookbook.ensure.useMutation({ onSuccess: () => void utils.lookbook.mine.invalidate(), onError: (error) => window.alert(error.message) });
  const profileDecision = trpc.memory.approveProfile.useMutation({ onSuccess: () => { void utils.memory.latestProfile.invalidate(); void utils.memory.currentProfile.invalidate(); } });
  const floralsFromProfile = trpc.memory.floralsFromProfile.useMutation({ onSuccess: (result) => setServerRecipe(result.recipe), onError: () => setServerRecipe(null) });
  const [tab, setTab] = useState(() => new URLSearchParams(window.location.search).get("tab") ?? "story");
  const [promptView, setPromptView] = useState<"human" | "machine">("human");
  const [seed, setSeed] = useState(42);
  const [midjourneyParameters, setMidjourneyParameters] = useState("--raw --exp 5 --q 2 --chaos 10 --stylize 125 --v 7");
  const [decisions, setDecisions] = useState<Record<string, "pending" | "accepted" | "rejected">>({});
  const [anchorLocked, setAnchorLocked] = useState(false);
  const [blueprintApproved, setBlueprintApproved] = useState(false);
  const [serverRecipe, setServerRecipe] = useState<ReturnType<typeof pickFlorals>["recipe"] | null>(null);
  const [layerOverrides, setLayerOverrides] = useState<Record<string, string>>({});
  const [sceneFiles, setSceneFiles] = useState<Record<number, { filename: string; mimeType: string; base64: string }>>({});
  const [wreathFile, setWreathFile] = useState<{ filename: string; mimeType: string; base64: string } | null>(null);
  const decide = trpc.floral.decide.useMutation({ onMutate: (input) => { const previous = decisions[input.itemId]; setDecisions((current) => ({ ...current, [input.itemId]: input.decision })); return { previous }; }, onSuccess: (result) => { setDecisions((current) => ({ ...current, [result.itemId]: result.decision })); void utils.floral.decisions.invalidate({ projectId: result.projectId }); }, onError: (error, input, context) => { setDecisions((current) => { const next = { ...current }; if (context?.previous) next[input.itemId] = context.previous; else delete next[input.itemId]; return next; }); window.alert(error.message); } });
  const renderQueue = trpc.render.reviewQueue.useQuery({ projectId: activeProjectId }, { enabled: fullStudioAccess && activeProjectId > 0 && (tab === "render" || tab === "lifestyle" || tab === "lookbook" || anchorLocked) });
  const uploadScene = trpc.render.upload.useMutation({ onSuccess: () => { setSceneFiles({}); renderQueue.refetch(); }, });
  const uploadWreath = trpc.render.upload.useMutation({ onSuccess: () => { setWreathFile(null); renderQueue.refetch(); } });
  const generateComet = trpc.render.generateComet.useMutation({ onSuccess: () => renderQueue.refetch(), onError: (error) => window.alert(error.message) });
  const enqueueLifestyle = trpc.render.enqueueComet.useMutation({ onSuccess: () => renderQueue.refetch(), onError: (error) => window.alert(error.message) });
  const reviewScene = trpc.render.review.useMutation({ onSuccess: () => renderQueue.refetch() });
  const readWreathFile = (file?: File) => { if (!file) return; const reader = new FileReader(); reader.onload = () => setWreathFile({ filename: file.name, mimeType: file.type || "image/png", base64: String(reader.result) }); reader.readAsDataURL(file); };
  useEffect(() => { if (savedDecisions) { const latest = Object.fromEntries([...savedDecisions].reverse().map((decision) => [decision.itemId, decision.decision])); setDecisions(latest); } }, [savedDecisions]);
  useEffect(() => { if (currentLookbook?.title) setLookbookTitleDraft(currentLookbook.title); }, [currentLookbook?.title]);
  useEffect(() => { if (user && currentProject === null && !ensureProject.isPending && !ensureProject.isSuccess) ensureProject.mutate({ name: "Untitled memory" }); }, [user, currentProject, ensureProject.isPending, ensureProject.isSuccess]);
  useEffect(() => { if (activeProjectId > 0 && currentProject && !currentLookbook && !ensureLookbook.isPending && !ensureLookbook.isSuccess) ensureLookbook.mutate({ projectId: activeProjectId, slug: `evercrafted-project-${activeProjectId}`, title: currentProject.name ?? "Your memory wreath" }); }, [activeProjectId, currentProject, currentLookbook, ensureLookbook.isPending, ensureLookbook.isSuccess]);
  const items = useMemo(() => { const catalog = inventory?.items?.length ? inventory.items.map((item) => ({ ...item, emotionTags: Array.isArray(item.emotionTags) ? item.emotionTags as string[] : [], stemLengthIn: item.stemLengthIn ? Number(item.stemLengthIn) : null })) : sampleItems; return mergeDecisionFallbackItems(catalog, sampleItems, (savedDecisions ?? []).map((decision) => decision.itemId)); }, [inventory, savedDecisions]);
  const profileForDisplay = (latestProfile?.profile ?? currentProfile?.profile) as EmotionalDesignProfile | undefined;
  const approvedProfile = currentProfile?.profile as EmotionalDesignProfile | undefined;
  const storyApproved = latestStory?.status === "approved";
  const profileApproved = currentProfile?.status === "approved";
  const sourceMemory = latestIntake?.memory ?? "";
  const canOpenTab = (key: string) => key === "story" || fullStudioAccess || (key === "selection" && storyApproved) || (key === "blueprint" && storyApproved && anchorLocked) || (key === "render" && storyApproved && anchorLocked && blueprintApproved) || (key === "lifestyle" && storyApproved && Boolean(approvedWreathAsset)) || (key === "lookbook" && storyApproved && Boolean(currentLookbook));
  const emotionalBrief = useMemo(() => buildCompositionBrief(approvedProfile), [approvedProfile]);
  const approvedFlorals = useMemo(() => getApprovedFlorals(items as FloralItem[], decisions), [items, decisions]);
  useEffect(() => { if (!activeProjectId || !currentProfile?.id) { setServerRecipe(null); return; } setServerRecipe(null); floralsFromProfile.mutate({ projectId: activeProjectId, profileId: currentProfile.id, seed }); }, [activeProjectId, currentProfile?.id, seed]);
  const anchorHandoffState = getAnchorHandoffState(approvedFlorals.length, anchorLocked);
  const transferAction = resolveAnchorTransfer(approvedFlorals.length, hasActiveProject);
  const handleAnchorTransfer = () => { if (!transferAction.canTransfer) return; setAnchorLocked(transferAction.locked); setTab(transferAction.nextTab); };
  const anchorSource = anchorLocked && approvedFlorals.length > 0 ? approvedFlorals : items;
  const recipe = useMemo(() => pickFlorals(anchorSource as FloralItem[], emotionalBrief, seed), [anchorSource, emotionalBrief, seed]);
  const showNoGreeneryPreview = new URLSearchParams(window.location.search).get("preview") === "no-greenery";
  const composedRecipe = serverRecipe ?? recipe.recipe;
  const displayedRecipe = showNoGreeneryPreview ? { ...composedRecipe, greenery: [] } : composedRecipe;
  const blueprint = useMemo(() => composeBlueprint(composedRecipe, emotionalBrief, seed), [composedRecipe, emotionalBrief, seed]);
  const ecr = useMemo(() => compileEcr(blueprint), [blueprint]);
  const wreathPrompt = useMemo(() => anchorLocked && approvedFlorals.length > 0 ? compileMidjourneyPrompt(blueprint, Object.fromEntries(approvedFlorals.map((item) => [item.itemId, item.name]))) : null, [anchorLocked, approvedFlorals, blueprint]);
  const prompt = wreathPrompt ?? { humanFacing: "Approve florals, then lock them into the wreath anchor to generate the wreath-only prompt.", machineFacing: "[STATUS] Wreath prompt locked until approved florals are transferred into the anchor." };
  const storyBeats = useMemo(() => Array.isArray(latestStory?.beats) ? latestStory.beats as Array<Record<string, unknown>> : [], [latestStory?.beats]);
  const scenePrompts = useMemo(() => { const approved = (renderQueue.data ?? []).find((asset) => asset.kind === "wreath" && (asset.status === "approved" || asset.status === "published")); const provenance = approved?.provenance; const generated = provenance && typeof provenance === "object" ? (provenance as { generatedScenePrompts?: unknown }).generatedScenePrompts : null; const persistedPrompts = Array.isArray(generated) && generated.length > 0 ? generated as ReturnType<typeof buildLifestyleScenePrompts> : null; const hasDynamicStructure = Boolean(persistedPrompts && persistedPrompts.every((scene) => typeof scene.prompt === "string" && scene.prompt.includes("Setting and action:") && scene.prompt.includes("Story direction:"))); const anchorReference = resolveSceneAnchorPrompt(wreathPrompt?.humanFacing ?? null, provenance); return storyBeats.length >= 3 ? buildLifestyleScenePrompts(anchorReference, storyBeats) : hasDynamicStructure && persistedPrompts ? persistedPrompts : buildLifestyleScenePrompts(anchorReference, storyBeats); }, [renderQueue.data, wreathPrompt?.humanFacing, storyBeats]);
  const scenePromptSource = useMemo(() => { const approved = (renderQueue.data ?? []).find((asset) => asset.kind === "wreath" && (asset.status === "approved" || asset.status === "published")); const provenance = approved?.provenance; return provenance && typeof provenance === "object" && Array.isArray((provenance as { generatedScenePrompts?: unknown }).generatedScenePrompts) ? "approved-wreath" : "story-beats"; }, [renderQueue.data]);
  const readSceneFile = (sceneIndex: number, file?: File) => { if (!file) return; const reader = new FileReader(); reader.onload = () => setSceneFiles((current) => ({ ...current, [sceneIndex]: { filename: file.name, mimeType: file.type || "image/png", base64: String(reader.result) } })); reader.readAsDataURL(file); };
  const renderStoryBeat = (entry: { name?: string; prompt?: string }, index: number) => { const scene = scenePrompts[index]; if (!activeProjectId || !scene) return; const handoff = buildLifestyleRenderHandoff(scene, index); enqueueLifestyle.mutate({ projectId: activeProjectId, kind: "lifestyle", operation: "imagine", model: "mj-fast-imagine", mode: "FAST", parameters: midjourneyParameters, prompt: handoff.prompt, parentAssetId: approvedWreathAsset?.id, sceneIndex: handoff.sceneIndex, sceneTitle: entry.name ?? handoff.sceneTitle, actionLabel: `Story beat ${handoff.sceneIndex + 1} lifestyle render` }); };
  const wreathAssets = (renderQueue.data ?? []).filter((asset) => asset.kind === "wreath");
  const approvedWreathAsset = wreathAssets.find((asset) => asset.status === "approved" || asset.status === "published");
  const approvedSceneAssets = (renderQueue.data ?? []).filter((asset) => asset.kind === "lifestyle" && (asset.status === "approved" || asset.status === "published"));
  useEffect(() => { if (tab !== "story" && capabilities && !canOpenTab(tab)) setTab("story"); }, [tab, capabilities, storyApproved, anchorLocked, blueprintApproved, approvedWreathAsset, currentLookbook]);
  // Manual-only rendering: locking the anchor never submits a provider task.

  if (loading) return <div className="grid min-h-screen place-items-center bg-[#f6f3ed] font-mono text-xs uppercase tracking-[.2em] text-[#806b4a]">Opening your workspace</div>;
  if (!user) return <div className="grid min-h-screen place-items-center bg-[#f6f3ed] px-6"><Card className="max-w-md border-[#dfd3c1] bg-[#fbfaf7]"><CardContent className="p-8"><p className="font-serif text-3xl">Your workspace begins with a memory.</p><Link href="/"><Button className="mt-6 rounded-full bg-[#304c3b]">Return to intake</Button></Link></CardContent></Card></div>;

  const tabs = [["story", "Story"], ["selection", "Florals"], ["blueprint", "Blueprint"], ["render", "Render studio"], ["lifestyle", "Lifestyle"], ["lookbook", "Lookbook"]];
  const activeStage = tab === "selection" ? "florals" : tab === "blueprint" ? "anchor" : tab === "render" ? (anchorLocked ? "wreathPrompt" : "gallery") : tab === "lifestyle" ? "scenes" : tab;
  return <main className="min-h-screen bg-[#f6f3ed] text-[#24231f]"><header className="flex items-center justify-between border-b border-[#ddd3c5] bg-[#fbfaf7] px-5 py-5 sm:px-10"><Link href="/" className="flex items-center gap-3 font-serif text-xl italic"><ArrowLeft size={16} /> Evercrafted</Link><div className="font-mono text-[10px] uppercase tracking-[.2em] text-[#81786c]">My workspace / {currentLookbook?.title ?? "The lake house in July"}</div></header><div className="mx-auto max-w-7xl px-5 py-10 sm:px-10"><div className="flex flex-wrap items-end justify-between gap-6"><div><p className="eyebrow">A living design file</p><h1 className="mt-3 font-serif text-6xl font-light leading-none">{currentLookbook?.title ?? latestStory?.title ?? "Your memory wreath"}</h1><p className="mt-4 font-serif text-lg italic text-[#736b60]">{latestStory?.metadata && typeof latestStory.metadata === "object" && "atmosphere" in latestStory.metadata ? String((latestStory.metadata as { atmosphere?: string }).atmosphere) : "Memory design"} · {emotionalBrief.formula} · {currentLookbook?.status ?? "draft"} 01</p></div><div className="flex items-center gap-3"><Badge variant="outline" className="rounded-full px-3 py-1 font-mono text-[9px] uppercase">{currentLookbook?.status ?? "client review"}</Badge><Link href="/photo-edits" className="rounded-full border border-[#cdbd9e] px-4 py-2 font-mono text-[9px] uppercase tracking-[.14em] text-[#6f5b3b]">Photo edits</Link><Button variant="outline" onClick={() => currentLookbook && lookbookShare.mutate({ id: currentLookbook.id })} disabled={!currentLookbook || lookbookShare.isPending} className="rounded-full border-[#cdbd9e] text-[#6f5b3b]"><Sparkles className="mr-2" size={15} /> {lookbookShare.isPending ? "Preparing link" : "Share preview"}</Button></div></div><nav className="mt-12 flex gap-1 overflow-auto border-b border-[#d9d0c3]">{tabs.map(([key, label]) => { const unlocked = canOpenTab(key); return <button key={key} disabled={!unlocked} onClick={() => unlocked && setTab(key)} className={`whitespace-nowrap px-4 py-4 font-mono text-[10px] uppercase tracking-[.18em] transition ${tab === key ? "border-b-2 border-[#304c3b] text-[#304c3b]" : unlocked ? "text-[#93887a] hover:text-[#304c3b]" : "cursor-not-allowed text-[#c5bbae]"}`}>{!unlocked && <Lock className="mr-1 inline" size={11} />}{label}</button>; })}</nav>
            <div className="mt-6 grid gap-8 lg:grid-cols-[220px_minmax(0,1fr)] lg:items-start"><aside className="lg:sticky lg:top-6"><div className="rounded-2xl border border-[#dfd3c1] bg-[#fbfaf7] p-4"><p className="eyebrow px-3">Page legend</p><p className="mt-2 px-3 font-serif text-lg leading-tight text-[#5d584e]">Every room in the studio, one step away.</p><nav aria-label="Workspace pages" className="mt-5 space-y-1">{workspacePageLegend.map((page) => <Link key={page.href} href={page.href} className={`block rounded-xl px-3 py-3 transition ${page.active ? "bg-[#304c3b] text-white" : "text-[#6f675d] hover:bg-[#f1ece2] hover:text-[#304c3b]"}`}><span className="block font-mono text-[10px] uppercase tracking-[.12em]">{page.label}</span><span className={`mt-1 block font-serif text-sm ${page.active ? "text-white/70" : "text-[#9a8d7c]"}`}>{page.detail}</span></Link>)}</nav></div></aside><div className="min-w-0"><div className="mt-0 rounded-2xl border border-[#e2d9cc] bg-[#fbfaf7] p-4 sm:p-5">
              <div className="flex flex-wrap items-center justify-between gap-3">
                <div><p className="eyebrow">Collection production path</p><p className="mt-1 font-serif text-lg text-[#5f584e]">The lookbook is assembled from an approved story, one wreath anchor, and three distinct scene beats.</p></div>
                <Badge variant="outline" className="rounded-full border-[#cdbd9e] font-mono text-[9px] uppercase tracking-[.14em]">{flowStages.findIndex((stage) => stage.key === activeStage) + 1} / {flowStages.length} in progress</Badge>
              </div>
              <div className="mt-5 grid gap-2 md:grid-cols-4 lg:grid-cols-8">
                {flowStages.map((stage, index) => { const unlocked = canOpenTab(stage.tab); return <button key={stage.key} disabled={!unlocked} onClick={() => unlocked && setTab(stage.tab)} className={`rounded-xl border p-3 text-left transition ${activeStage === stage.key ? "border-[#304c3b] bg-[#304c3b] text-white" : index < flowStages.findIndex((item) => item.key === activeStage) ? "border-[#d8c9ad] bg-[#f3eee5] text-[#5d6c60]" : unlocked ? "border-[#e4dbcf] bg-white text-[#877d70]" : "cursor-not-allowed border-[#eee8df] bg-[#faf8f4] text-[#b9afa1]"}`}><span className="font-mono text-[9px] uppercase tracking-[.14em] opacity-70">0{index + 1}</span><span className="mt-2 block font-serif text-base leading-tight">{!unlocked && <Lock className="mr-1 inline" size={11} />}{stage.label}</span><span className="mt-1 block text-[10px] leading-snug opacity-70">{unlocked ? stage.detail : "Complete the previous stage first."}</span></button>; })}
              </div>
            </div><section className="mt-6 rounded-2xl border border-[#dfd3c1] bg-[#fbfaf7] px-5 py-5"><div className="flex flex-wrap items-start justify-between gap-4"><div><p className="eyebrow">Emotional design gate</p><p className="mt-2 font-serif text-xl">{latestProfile ? `Profile v${latestProfile.version} · ${latestProfile.status.replace("_", " ")}` : "No emotional profile generated yet"}</p><p className="mt-1 max-w-2xl font-serif text-sm text-[#80776b]">{latestProfile?.status === "approved" ? "This is the approved emotional source for Story Genesis, florals, and blueprint composition." : latestIntake ? "Read the generated profile below, then approve or request a revision before Story Genesis." : "This project has no saved memory intake yet. Return to the main page to begin the guided journey."}</p></div><div className="flex flex-wrap gap-2">{!latestIntake && <Link href="/"><Button variant="outline" className="rounded-full border-[#cdbd9e] text-[#6f5b3b]">Return to memory intake</Button></Link>}{latestIntake && latestProfile?.status !== "awaiting_approval" && <Button disabled={generateProfile.isPending} onClick={() => generateProfile.mutate({ projectId: activeProjectId, intakeId: latestIntake.id, memory: latestIntake.memory, occasion: latestIntake.occasion, location: String(latestIntake.location ?? ""), timeOfDay: String(latestIntake.timeOfDay ?? "") })} className="rounded-full bg-[#304c3b]">{generateProfile.isPending ? "Reading memory…" : latestProfile ? "Regenerate from current memory" : "Generate emotional reading"}</Button>}{latestProfile?.status === "awaiting_approval" && <><Button disabled={profileDecision.isPending} onClick={() => profileDecision.mutate({ id: latestProfile.id, decision: "approved", overrides: {} })} className="rounded-full bg-[#304c3b]">Approve reading</Button><Button disabled={profileDecision.isPending} variant="outline" onClick={() => profileDecision.mutate({ id: latestProfile.id, decision: "revision_requested", overrides: {} })} className="rounded-full border-[#cdbd9e] text-[#6f5b3b]">Request revision</Button></>}</div></div>{profileForDisplay && <div className="mt-6 grid gap-4 lg:grid-cols-[1.25fr_.75fr]"><div className="rounded-2xl border border-[#e5dccf] bg-[#f6f1e9] p-5"><p className="eyebrow">Generated reading</p><p className="mt-3 font-serif text-2xl leading-tight">{profileForDisplay.atmosphere.atmosphereArchetype}</p><p className="mt-3 font-serif text-base leading-relaxed text-[#665e54]">{latestProfile?.summary ?? `${profileForDisplay.emotionalCore.primaryEmotion} · ${profileForDisplay.movementEnergy.directionalEnergy}`}</p><div className="mt-5 grid gap-3 sm:grid-cols-3"><div><p className="font-mono text-[9px] uppercase tracking-[.14em] text-[#9a7b50]">Primary emotion</p><p className="mt-1 font-serif text-lg">{profileForDisplay.emotionalCore.primaryEmotion}</p></div><div><p className="font-mono text-[9px] uppercase tracking-[.14em] text-[#9a7b50]">Movement</p><p className="mt-1 font-serif text-lg">{profileForDisplay.movementEnergy.movementArchetype.join(" + ")}</p></div><div><p className="font-mono text-[9px] uppercase tracking-[.14em] text-[#9a7b50]">Composition</p><p className="mt-1 font-serif text-lg">{profileForDisplay.wreathTranslation.compositionFormula}</p></div></div></div><div className="rounded-2xl bg-[#26342b] p-5 text-[#f8f4eb]"><p className="eyebrow text-[#d8bb84]">Palette and spatial direction</p><p className="mt-3 font-serif text-lg">{[profileForDisplay.paletteSystem.dominantColor.name, ...profileForDisplay.paletteSystem.supportingColors.map((color) => color.name)].join(" · ")}</p><p className="mt-4 font-serif text-sm leading-relaxed text-white/70">{profileForDisplay.movementEnergy.directionalEnergy}. Silence stays in the {profileForDisplay.asymmetryComposition.silenceZone}.</p></div></div>}</section>

{tab === "story" && <section className="grid gap-8 py-12 lg:grid-cols-[1.1fr_.9fr]">{latestStory ? <div className="lg:col-span-2 rounded-3xl border border-[#dfd3c1] bg-[#fbfaf7] p-8 sm:p-12"><div className="flex flex-wrap items-start justify-between gap-4"><div><p className="eyebrow">Story Genesis / version {latestStory.version}</p><h2 className="mt-4 max-w-4xl font-serif text-5xl font-light leading-[.96]">{latestStory.title}</h2></div><div className="flex items-center gap-3"><Badge className={latestStory.status === "approved" ? "bg-[#304c3b]" : "bg-[#aa8451]"}>{latestStory.status.replace("_", " ")}</Badge>{latestStory.status === "awaiting_approval" && <Button disabled={approveStory.isPending} onClick={() => approveStory.mutate({ storyId: latestStory.id, decision: "approved" })} className="rounded-full bg-[#304c3b]">Approve Story Genesis</Button>}</div></div><p className="mt-8 max-w-4xl whitespace-pre-wrap font-serif text-xl leading-relaxed text-[#5d584f]">{latestStory.body}</p><div className="mt-10 border-t border-[#e8e0d5] pt-8"><div className="flex items-center justify-between"><p className="eyebrow">Cinematic beats / {Array.isArray(latestStory.beats) ? latestStory.beats.length : 0}</p><span className="font-mono text-[9px] uppercase tracking-[.14em] text-[#8c8173]">External render handoff</span></div><div className="mt-5 grid gap-3 md:grid-cols-2 lg:grid-cols-3">{(Array.isArray(latestStory.beats) ? latestStory.beats : []).map((beat, index) => { const entry = beat as { name?: string; role?: string; setting?: string; camera?: string; light?: string; prompt?: string }; const beatAsset = (renderQueue.data ?? []).find((asset) => asset.kind === "lifestyle" && (asset.provenance as { sceneIndex?: number } | null)?.sceneIndex === index); return <article key={`${entry.name ?? "beat"}-${index}`} className="rounded-2xl border border-[#e3dacd] bg-[#f5f0e8] p-5"><div className="flex items-center justify-between"><span className="font-mono text-[9px] uppercase tracking-[.14em] text-[#9a7b50]">Beat 0{index + 1}</span><span className="font-mono text-[9px] uppercase tracking-[.1em] text-[#81786d]">{beatAsset?.status ?? "awaiting render"}</span></div><h3 className="mt-4 font-serif text-2xl leading-tight">{entry.name ?? `Story beat ${index + 1}`}</h3><p className="mt-2 font-mono text-[9px] uppercase tracking-[.12em] text-[#8b7d6d]">{entry.role ?? "Narrative moment"}</p><p className="mt-4 font-serif text-sm leading-relaxed text-[#6f675d]">{entry.setting ?? "A lived-in place shaped by the approved emotional profile."}</p><p className="mt-4 border-t border-[#dfd3c1] pt-3 font-mono text-[9px] leading-relaxed text-[#85796b]">{entry.camera ?? "Camera direction held for external render."} · {entry.light ?? "Light direction held for external render."}</p>{entry.prompt && <details className="mt-4"><summary className="cursor-pointer font-mono text-[9px] uppercase tracking-[.12em] text-[#6f5b3b]">View lifestyle render prompt</summary><p className="mt-3 font-mono text-[10px] leading-relaxed text-[#6f675d]">{scenePrompts[index]?.prompt ?? entry.prompt}</p></details>}<div className="mt-5 flex flex-wrap items-center justify-between gap-3 border-t border-[#dfd3c1] pt-4">{beatAsset?.url && <img src={beatAsset.url} alt={`${entry.name ?? "Story beat"} lifestyle render`} className="h-16 w-24 rounded-lg object-cover" />}{beatAsset?.status === "approved" || beatAsset?.status === "published" ? <span className="font-mono text-[9px] uppercase tracking-[.1em] text-[#304c3b]">Ready in Lifestyle</span> : <Button disabled={enqueueLifestyle.isPending || !hasActiveProject || !storyApproved || !entry.prompt} onClick={() => renderStoryBeat(entry, index)} className="rounded-full bg-[#304c3b] px-4 py-2 font-mono text-[9px] uppercase tracking-[.12em]">{enqueueLifestyle.isPending ? "Submitting render…" : beatAsset?.status === "review" ? "Review in Lifestyle" : "Render this lifestyle image"}</Button>}</div></article>; })}</div></div></div> : <div className="lg:col-span-2 rounded-3xl border border-[#dfd3c1] bg-[#fbfaf7] p-8 sm:p-10"><p className="eyebrow">Story Genesis / protected generation</p><h2 className="mt-4 font-serif text-4xl font-light">Give the approved feeling a longer room to speak.</h2><p className="mt-3 max-w-2xl font-serif text-lg leading-relaxed text-[#756d62]">This server-side pass creates the complete 600–800 word five-movement narrative and its 7–9 cinematic lifestyle beats. It remains blocked until an Emotional Design Profile is approved.</p><div className="mt-6 rounded-2xl border border-[#dfd3c1] bg-[#f7f3ec] p-5"><p className="eyebrow">Source memory / persisted from intake</p><p className="mt-3 whitespace-pre-wrap font-serif text-lg leading-relaxed text-[#5f584e]">{sourceMemory || "Your saved memory is still loading."}</p><p className="mt-4 font-mono text-[9px] uppercase tracking-[.12em] text-[#958979]">{latestIntake ? `${latestIntake.occasion} · ${latestIntake.timeOfDay}` : "No persisted intake"}</p></div><Button disabled={!profileApproved || !sourceMemory || generateStory.isPending} onClick={() => currentProfile && generateStory.mutate({ projectId: activeProjectId, profileId: currentProfile.id, memory: sourceMemory, location: String(latestIntake?.location ?? currentProject?.name ?? "the remembered house"), honoree: String(latestIntake?.honoree ?? "") })} className="mt-5 rounded-full bg-[#304c3b]">{generateStory.isPending ? "Writing the five movements…" : "Generate the full Story Genesis"}</Button>{generateStory.error && <p className="mt-3 text-sm text-red-700">{generateStory.error.message}</p>}</div>}<article className="rounded-3xl bg-[#26342b] p-8 text-[#f8f4eb] sm:p-12"><p className="eyebrow text-[#d8bb84]">Atmosphere / {profileForDisplay?.atmosphere.atmosphereArchetype ?? "Awaiting emotional reading"}</p><h2 className="mt-6 max-w-xl font-serif text-5xl font-light leading-[.96]">{profileForDisplay ? `${profileForDisplay.emotionalCore.primaryEmotion} moves through this memory.` : "The emotional direction will appear here."}</h2><p className="mt-8 max-w-2xl font-serif text-xl leading-relaxed text-white/75">{latestStory?.body?.slice(0, 420) ?? (profileForDisplay ? `${profileForDisplay.movementEnergy.directionalEnergy}. The story, florals, and blueprint will inherit this emotional direction after approval.` : "Generate the emotional reading above to begin the memory-driven design path.")}</p><div className="mt-12 grid gap-3 sm:grid-cols-3">{[["Palette", profileForDisplay ? [profileForDisplay.paletteSystem.dominantColor.name, ...profileForDisplay.paletteSystem.supportingColors.map((color) => color.name)].join(" · ") : "Awaiting profile"], ["Movement", profileForDisplay?.movementEnergy.directionalEnergy ?? "Awaiting profile"], ["Silence", profileForDisplay?.asymmetryComposition.silenceZone ?? "Awaiting profile"]].map(([title, text]) => <div key={title} className="border-t border-white/20 pt-3"><div className="font-mono text-[9px] uppercase tracking-[.16em] text-[#d8bb84]">{title}</div><div className="mt-3 font-serif text-lg">{text}</div></div>)}</div>{storyApproved && <Button onClick={() => setTab("selection")} className="mt-12 rounded-full bg-[#d8bb84] text-[#26342b] hover:bg-[#e5cea3]">Continue to Florals <Leaf className="ml-2" size={15} /></Button>}</article><div className="rounded-3xl border border-[#dfd3c1] bg-[#fbfaf7] p-8"><p className="eyebrow">Five movements</p><div className="mt-8 space-y-5">{["The world", "The character enters", "The gathering", "The making", "The after"].map((item, index) => <div key={item} className="flex gap-4 border-b border-[#eee8df] pb-5"><span className="font-mono text-[10px] text-[#aa8a59]">0{index + 1}</span><div><h3 className="font-serif text-2xl font-light">{item}</h3><p className="mt-1 font-serif text-base text-[#80776b]">A cinematic beat is ready for review.</p></div></div>)}</div></div></section>}

{tab === "selection" && <section className="py-12"><div className="mb-8 flex flex-wrap items-end justify-between gap-5"><div><p className="eyebrow">Emotion-driven selection</p><h2 className="mt-3 font-serif text-5xl font-light">These stems arrived from your memory.</h2></div><Button variant="outline" onClick={() => setSeed((current) => current + 1)} className="rounded-full border-[#cdbd9e] text-[#6f5b3b]">Re-roll seed · {seed}</Button></div><div className="grid gap-4 md:grid-cols-2 lg:grid-cols-4">{(Object.entries(displayedRecipe) as Array<[string, typeof recipe.recipe.focal]>).map(([role, roleItems]) => <Card key={role} className="border-[#dfd3c1] bg-[#fbfaf7]"><CardContent className="p-5"><p className="eyebrow">{role}</p><div className="mt-5 space-y-4">{roleItems.map((item) => <div key={item.itemId} className="border-b border-[#eee8df] pb-3"><div className="flex items-center gap-3"><span className="h-6 w-6 rounded-full border border-black/10" style={{ background: item.colorHex ?? "#bcb5a3" }} /><div className="font-serif text-lg">{item.name}</div></div><p className="mt-2 font-serif text-sm italic text-[#82776a]">{item.selectionReason}</p><div className="mt-2 flex items-center justify-between gap-2 font-mono text-[9px] uppercase tracking-[.12em] text-[#948879]"><span>Tier {item.tier} · {item.estimatedPieces} pieces</span><span className="flex flex-wrap gap-2"><button type="button" aria-pressed={decisions[item.itemId] === "accepted"} disabled={!hasActiveProject || decide.isPending} onClick={() => hasActiveProject && decide.mutate({ projectId: activeProjectId, itemId: item.itemId, seed, role, decision: "accepted", explanation: item.selectionReason })} className={`inline-flex min-h-10 items-center gap-1.5 rounded-full border px-4 py-2 font-mono text-[10px] font-semibold uppercase tracking-[.12em] transition active:scale-[.97] disabled:cursor-not-allowed disabled:opacity-45 ${decisions[item.itemId] === "accepted" ? "border-[#304c3b] bg-[#304c3b] text-white shadow-md" : "border-[#73927c] bg-[#edf5ee] text-[#304c3b] hover:bg-[#dcebdd]"}`}><Check size={14} />{decisions[item.itemId] === "accepted" ? "Accepted" : "Accept"}</button><button type="button" aria-pressed={decisions[item.itemId] === "rejected"} disabled={!hasActiveProject || decide.isPending} onClick={() => hasActiveProject && decide.mutate({ projectId: activeProjectId, itemId: item.itemId, seed, role, decision: "rejected", explanation: item.selectionReason })} className={`inline-flex min-h-10 items-center gap-1.5 rounded-full border px-4 py-2 font-mono text-[10px] font-semibold uppercase tracking-[.12em] transition active:scale-[.97] disabled:cursor-not-allowed disabled:opacity-45 ${decisions[item.itemId] === "rejected" ? "border-[#9a4b45] bg-[#9a4b45] text-white shadow-md" : "border-[#c98f88] bg-[#fff1ef] text-[#9a4b45] hover:bg-[#f9dfdc]"}`}><X size={14} />{decisions[item.itemId] === "rejected" ? "Rejected" : "Reject"}</button></span></div></div>)}</div></CardContent></Card>)}</div>{displayedRecipe.greenery.length === 0 && <div className="mt-8 rounded-2xl border border-[#e2c9a5] bg-[#fff8ec] p-5"><p className="eyebrow text-[#80613d]">Inventory gap / greenery</p><p className="mt-2 max-w-2xl font-serif text-lg leading-relaxed text-[#6f6252]">No approved greenery matched this emotional recipe yet. Add or approve foliage in Inventory, then reroll the seed to complete the inner wreath ring.</p></div>}<div className="mt-8 flex flex-wrap gap-3">{!hasActiveProject && <p className="w-full rounded-xl border border-[#e2c9a5] bg-[#fff8ec] px-4 py-3 font-mono text-[10px] uppercase tracking-[.1em] text-[#80613d]">Your active project is still opening. Floral decisions will unlock when it is available.</p>}<Button type="button" disabled={!hasActiveProject || anchorHandoffState === "blocked"} onClick={handleAnchorTransfer} className={`rounded-full px-5 py-3 font-mono text-[10px] font-semibold uppercase tracking-[.12em] shadow-sm transition-colors active:scale-[.98] ${anchorHandoffState === "locked" ? "bg-[#1e3529] text-white shadow-md hover:bg-[#17291f]" : anchorHandoffState === "ready" ? "bg-[#304c3b] text-white shadow-md hover:bg-[#1e3529]" : "bg-[#d8bb84] text-[#5c4b32] hover:bg-[#cdb074] disabled:cursor-not-allowed disabled:opacity-70"}`}><Map className="mr-2" size={15} />{anchorHandoffState === "locked" ? "Florals transferred · Wreath anchor locked" : anchorHandoffState === "ready" ? "Transfer approved florals to wreath anchor" : "Approve florals to unlock transfer"}</Button><span className={`self-center rounded-full px-3 py-2 font-mono text-[9px] uppercase tracking-[.12em] ${anchorHandoffState === "locked" ? "bg-[#e5f0e6] text-[#304c3b]" : anchorHandoffState === "ready" ? "bg-[#e5f0e6] text-[#304c3b]" : "bg-[#f1ece2] text-[#988b7a]"}`}>{anchorHandoffState === "locked" ? `${approvedFlorals.length} florals locked into anchor` : anchorHandoffState === "ready" ? `${approvedFlorals.length} approved florals ready` : "Approve at least one floral first"}</span></div></section>}

{tab === "blueprint" && <section className="grid gap-8 py-12 lg:grid-cols-[1fr_.8fr]"><Card className="border-[#dfd3c1] bg-[#fbfaf7]"><CardContent className="p-6 sm:p-10"><div className="flex items-center justify-between"><div><p className="eyebrow">EC_WR_V2 · seed {blueprint.seed}</p><h2 className="mt-3 font-serif text-5xl font-light">{emotionalBrief.formula} blueprint</h2><p className="mt-3 max-w-xl font-serif text-base leading-relaxed text-[#756d62]">Generated from the approved {profileForDisplay?.emotionalCore.primaryEmotion ?? "emotional"} profile and {approvedFlorals.length} approved inventory florals. Review the map below before approval.</p></div><Badge className="bg-[#304c3b]">Deterministic</Badge></div><div className="mt-5 rounded-xl border border-[#e2d9cc] bg-[#f6f1e9] px-4 py-3 font-mono text-[9px] uppercase tracking-[.12em] text-[#806f5a]">Approval target: {blueprint.objects.length} placements · silence arc {blueprint.silenceArc?.join("°–")} · {approvedFlorals.length} approved stems</div><div className="relative mx-auto mt-10 aspect-square max-w-[520px] rounded-full border border-[#cbbda6] bg-[#f1ece2]"><div className="absolute inset-[18%] rounded-full border border-dashed border-[#cbbda6]" />{blueprint.objects.map((object) => { const angle = object.theta * Math.PI / 180; const left = 50 + object.radius * 42 * Math.sin(angle); const top = 50 - object.radius * 42 * Math.cos(angle); return <div key={object.id} title={`${object.asset} at ${object.theta}°`} className={`absolute h-8 w-8 -translate-x-1/2 -translate-y-1/2 rounded-full border-2 border-[#fbfaf7] shadow ${(layerOverrides[object.id] ?? object.layer) === "focal" ? "bg-[#7a3343]" : (layerOverrides[object.id] ?? object.layer) === "secondary" ? "bg-[#9d88ba]" : (layerOverrides[object.id] ?? object.layer) === "greenery" ? "bg-[#57745d]" : "bg-[#b78950]"}`} style={{ left: `${left}%`, top: `${top}%` }} />; })}<div className="absolute left-1/2 top-1/2 -translate-x-1/2 -translate-y-1/2 text-center font-mono text-[9px] uppercase tracking-[.12em] text-[#8d806e]">silence<br />45°–135°</div></div></CardContent></Card><Card className="border-[#dfd3c1] bg-[#26342b] text-[#f8f4eb]"><CardContent className="p-8"><p className="eyebrow text-[#d8bb84]">Build intelligence</p><div className="mt-7 space-y-5">{[["Objects", `${blueprint.objects.length} placed stems`], ["Outer diameter", "24 inches"], ["Layer order", "greenery → filler → secondary → focal"], ["Package", "ECR 1.1 · proof gate"], ["Ring bands", blueprint.ringBands.map((band) => `${band.name} / ${band.role}`).join(" · ")], ["Clusters", Object.entries(blueprint.clusters).map(([name, ids]) => `${name} (${ids.length})`).join(" · ")]].map(([label, value]) => <div key={label} className="border-b border-white/15 pb-4"><div className="font-mono text-[9px] uppercase tracking-[.16em] text-[#d8bb84]">{label}</div><div className="mt-2 font-serif text-xl">{value}</div></div>)}</div><div className="mt-8 rounded-xl border border-white/15 bg-white/5 p-4"><div className="font-mono text-[9px] uppercase tracking-[.16em] text-[#d8bb84]">Blueprint approval gate</div><p className="mt-2 font-serif text-lg text-white/80">{blueprintApproved ? "Blueprint approved for a human-controlled wreath render." : "Review the radial placement map, layer order, stem counts, and protected silence arc before approving this blueprint."}</p><Button type="button" onClick={() => setBlueprintApproved((current) => !current)} disabled={!anchorLocked || !approvedFlorals.length} className={`mt-4 rounded-full ${blueprintApproved ? "bg-[#1e3529] text-white" : "bg-[#d8bb84] text-[#26342b]"}`}>{blueprintApproved ? "Blueprint approved · click to revoke" : "Approve blueprint for rendering"}<Check className="ml-2" size={15} /></Button><div className="mt-5 border-t border-white/15 pt-4"><div className="font-mono text-[9px] uppercase tracking-[.16em] text-[#d8bb84]">Wreath anchor handoff</div><p className="mt-2 font-serif text-lg text-white/80">{anchorLocked ? `${approvedFlorals.length} approved florals are now locked into the wreath-only prompt.` : "Transfer approved florals from the Florals stage before generating the wreath-only prompt."}</p><Button disabled={!anchorLocked || !approvedFlorals.length || !blueprintApproved} onClick={() => setTab("render")} className="mt-4 rounded-full bg-[#d8bb84] text-[#26342b]">Open wreath-only prompt <Sparkles className="ml-2" size={15} /></Button></div></div><div className="mt-8 rounded-xl border border-white/15 bg-white/5 p-4"><div className="font-mono text-[9px] uppercase tracking-[.16em] text-[#d8bb84]">Editable layer review</div><div className="mt-3 grid gap-2 sm:grid-cols-2">{blueprint.objects.slice(0, 12).map((object) => <label key={`layer-${object.id}`} className="flex items-center justify-between gap-3 font-mono text-[9px] uppercase tracking-[.08em] text-white/70"><span className="truncate">{object.asset}</span><select aria-label={`Layer for ${object.asset}`} value={layerOverrides[object.id] ?? object.layer} onChange={(event) => { setBlueprintApproved(false); setLayerOverrides((current) => ({ ...current, [object.id]: event.target.value })); }} className="rounded border border-white/20 bg-[#1e2b24] px-2 py-1 text-[#f8f4eb]"><option value="greenery">greenery</option><option value="filler">filler</option><option value="secondary">secondary</option><option value="focal">focal</option></select></label>)}</div></div><div className="mt-8 flex gap-3"><Button disabled={capabilities ? !capabilities.canDownloadBlueprint : false} onClick={() => downloadJson(`evercrafted-maker-${blueprint.seed}.json`, blueprint)} className="rounded-full bg-[#d8bb84] text-[#26342b]"><Download className="mr-2" size={15} /> {capabilities?.canDownloadBlueprint ? "Maker package" : "Maker tier required"}</Button><Button variant="outline" onClick={() => downloadText(buildSheetFilename(blueprint.seed), buildPrintableBuildSheet({ blueprint, items }))} className="rounded-full border-white/30 bg-transparent text-white">Export build sheet</Button><Button disabled={capabilities ? !capabilities.canPackageEcr : false} onClick={() => downloadJson(`evercrafted-${blueprint.seed}.ecrpkg`, buildEcrPackage(ecr, items, `blueprint-${blueprint.seed}`))} variant="outline" className="rounded-full border-white/30 bg-transparent text-white"><Lock className="mr-2" size={15} /> {capabilities?.canPackageEcr ? "Export ECR package" : "Studio tier"}</Button></div></CardContent></Card></section>}

{tab === "render" && <section className="py-12"><div className="grid gap-8 lg:grid-cols-[.9fr_1.1fr]"><Card className="border-[#dfd3c1] bg-[#fbfaf7]"><CardContent className="p-8 sm:p-10"><p className="eyebrow">Wreath render / dedicated review</p><h2 className="mt-4 font-serif text-5xl font-light">Return the wreath before it enters a room.</h2><p className="mt-5 font-serif text-lg leading-relaxed text-[#756d62]">This card is only for the approved wreath render. Lifestyle scene images belong in the separate Scene prompts stage.</p><div className="mt-6 rounded-2xl border border-[#e1d7c8] bg-[#f3eee5] p-5"><p className="font-mono text-[9px] uppercase tracking-[.16em] text-[#8d7b61]">Wreath-only prompt</p><pre className="mt-3 whitespace-pre-wrap font-mono text-xs leading-relaxed text-[#5c554b]">{prompt.humanFacing}</pre></div><label className="mt-4 block font-mono text-[9px] uppercase tracking-[.14em] text-[#8d7b61]">Midjourney parameters<Input value={midjourneyParameters} onChange={(event) => setMidjourneyParameters(event.target.value)} className="mt-2 font-mono text-xs" /></label><div className="mt-5 flex flex-wrap gap-2"><Button onClick={() => navigator.clipboard?.writeText(prompt.humanFacing)} className="rounded-full bg-[#304c3b]"><Copy className="mr-2" size={15} /> Copy wreath prompt</Button><Button variant="outline" onClick={() => downloadText(`evercrafted-wreath-${seed}-prompt.txt`, prompt.humanFacing)} className="rounded-full border-[#cdbd9e] text-[#6f5b3b]">Download prompt</Button><Button disabled={!canManuallyRenderWreath({ hasActiveProject, anchorLocked, blueprintApproved }) || generateComet.isPending} onClick={() => enqueueLifestyle.mutate({ projectId: activeProjectId, kind: "wreath", operation: "imagine", model: "mj-fast-imagine", mode: "FAST", parameters: midjourneyParameters, prompt: prompt.humanFacing, actionLabel: "Manual wreath render" })} className="rounded-full bg-[#d8bb84] text-[#26342b]"><Wand2 className="mr-2" size={15} />{enqueueLifestyle.isPending ? "Submitting wreath render…" : blueprintApproved ? "Render with Midjourney" : "Approve blueprint to render"}</Button></div><label className="mt-6 flex cursor-pointer items-center gap-3 rounded-xl border border-dashed border-[#cdbd9e] bg-[#f8f5ef] px-4 py-4 font-mono text-[10px] uppercase tracking-[.12em] text-[#756b5d]"><ImagePlus size={17} className="text-[#a47c45]" /><span className="truncate">{wreathFile?.filename ?? "Choose returned wreath render"}</span><input type="file" accept="image/*" className="hidden" onChange={(event) => readWreathFile(event.target.files?.[0])} /></label><Button disabled={!hasActiveProject || !wreathFile || uploadWreath.isPending || !anchorLocked} onClick={() => hasActiveProject && wreathFile && uploadWreath.mutate({ projectId: activeProjectId, kind: "wreath", ...wreathFile, prompt: prompt.humanFacing })} className="mt-3 w-full rounded-full bg-[#d8bb84] text-[#26342b]"><Upload className="mr-2" size={15} /> {uploadWreath.isPending ? "Uploading wreath render" : "Upload wreath for review"}</Button></CardContent></Card><Card className="border-[#dfd3c1] bg-[#26342b] text-[#f8f4eb]"><CardContent className="p-8 sm:p-10"><p className="eyebrow text-[#d8bb84]">Wreath review queue</p><h3 className="mt-4 font-serif text-3xl font-light">The anchor image stays separate.</h3>{wreathAssets.length === 0 ? <p className="mt-6 font-serif text-lg text-white/70">No wreath render has been returned yet.</p> : <div className="mt-6 space-y-4">{wreathAssets.map((asset) => <div key={asset.id} className="overflow-hidden rounded-2xl border border-white/15 bg-white/5"><img src={asset.url} alt="Returned wreath render" className="aspect-[4/3] w-full object-cover" /><div className="flex items-center justify-between gap-3 p-4"><span className="font-mono text-[9px] uppercase tracking-[.14em] text-white/60">{asset.status}</span>{asset.status === "review" && user?.role === "admin" ? <span className="flex gap-3 font-mono text-[9px] uppercase"><button onClick={() => reviewScene.mutate({ assetId: asset.id, status: "approved" })} className="text-[#d8bb84]">Approve</button><button onClick={() => reviewScene.mutate({ assetId: asset.id, status: "rejected", rejectionReason: "Needs a new wreath variation." })} className="text-[#f0a29b]">Reject</button></span> : asset.status === "approved" || asset.status === "published" ? <span className="flex items-center gap-2 font-mono text-[9px] uppercase text-[#d8bb84]"><Check size={15} /> Approved wreath anchor</span> : null}</div></div>)}</div>}</CardContent></Card></div></section>}

{tab === "lifestyle" && <section className="py-12"><div className="flex flex-wrap items-end justify-between gap-5"><div><p className="eyebrow">Lifestyle scene prompts / three placements</p><h2 className="mt-4 max-w-3xl font-serif text-5xl font-light">Let the story leave the studio.</h2><p className="mt-5 max-w-2xl font-serif text-lg leading-relaxed text-[#756d62]">Each scene now has a copyable prompt, a placement brief, an upload slot, and a review state. Render externally, then return the image to the exact beat that created it.</p></div><Badge className="rounded-full bg-[#304c3b] px-4 py-2 font-mono text-[9px] uppercase tracking-[.16em]">{scenePrompts.length} scene prompts ready</Badge></div><div className="mt-10 space-y-6">{scenePrompts.map((scene, index) => { const sceneAssets = (renderQueue.data ?? []).filter((asset) => asset.kind === "lifestyle" && (asset.provenance as { sceneIndex?: number } | null)?.sceneIndex === index); const selectedFile = sceneFiles[index]; return <Card key={scene.title} className="overflow-hidden border-[#dfd3c1] bg-[#fbfaf7]"><div className="grid lg:grid-cols-[.82fr_1.18fr]"><div className={index === 0 ? "bg-gradient-to-br from-[#819080] via-[#cbb996] to-[#405148] p-7 text-white" : index === 1 ? "bg-gradient-to-br from-[#b18b68] via-[#d9cdb7] to-[#5c6f62] p-7 text-white" : "bg-gradient-to-br from-[#283b35] via-[#788b77] to-[#c9a975] p-7 text-white"}><div className="flex items-center justify-between"><span className="font-mono text-[9px] uppercase tracking-[.2em] text-white/75">Scene {scene.number}</span><span className="rounded-full border border-white/30 px-2 py-1 font-mono text-[9px] uppercase tracking-[.12em] text-white/75">{scene.context}</span></div><h3 className="mt-24 max-w-[10ch] font-serif text-4xl leading-[.95]">{scene.title}</h3><p className="mt-4 font-serif text-base leading-relaxed text-white/80">{scene.body}</p><div className="mt-5 border-t border-white/25 pt-3 font-mono text-[9px] uppercase leading-relaxed tracking-[.12em] text-white/70">{scene.placement}</div></div><CardContent className="p-6 sm:p-8"><div className="flex flex-wrap items-center justify-between gap-3"><div><p className="eyebrow">Render handoff</p><p className="mt-1 font-serif text-xl">{scenePromptSource === "approved-wreath" ? "Generated from the approved wreath render. Copy the prompt, render the scene, upload the return." : "Approve the wreath render to generate these lifestyle prompts automatically."}</p></div><Badge variant="outline" className="font-mono text-[9px] uppercase">{sceneAssets[0]?.status ?? "awaiting render"}</Badge></div><div className="mt-5 rounded-xl border border-[#e4dbce] bg-[#f3eee5] p-4"><p className="font-mono text-[9px] uppercase tracking-[.14em] text-[#8d7b61]">Scene prompt</p><p className="mt-3 whitespace-pre-wrap font-mono text-xs leading-relaxed text-[#5c554b]">{scene.prompt}</p></div><div className="mt-4 flex flex-wrap gap-2"><Button size="sm" onClick={() => navigator.clipboard?.writeText(scene.prompt)} className="rounded-full bg-[#304c3b]"><Copy className="mr-2" size={14} /> Copy scene prompt</Button><Button size="sm" variant="outline" onClick={() => downloadText("evercrafted-scene-" + scene.number + "-prompt.txt", scene.prompt)} className="rounded-full border-[#cdbd9e] text-[#6f5b3b]"><Download className="mr-2" size={14} /> Download prompt</Button><Button size="sm" disabled={!hasActiveProject || generateComet.isPending} onClick={() => enqueueLifestyle.mutate({ projectId: activeProjectId, kind: "lifestyle", operation: "imagine", model: "mj-fast-imagine", mode: "FAST", parameters: midjourneyParameters, prompt: scene.prompt, sceneIndex: index, sceneTitle: scene.title, parentAssetId: approvedWreathAsset?.id, actionLabel: `Lifestyle scene ${index + 1} render` })} className="rounded-full bg-[#d8bb84] text-[#26342b]"><Wand2 className="mr-2" size={14} />{enqueueLifestyle.isPending ? "Submitting render…" : "Render this scene"}</Button></div><div className="mt-6 grid gap-3 sm:grid-cols-[1fr_auto]"><label className="flex cursor-pointer items-center gap-3 rounded-xl border border-dashed border-[#cdbd9e] bg-[#f8f5ef] px-4 py-3 font-mono text-[10px] uppercase tracking-[.12em] text-[#756b5d]"><ImagePlus size={16} className="text-[#a47c45]" /><span className="truncate">{selectedFile?.filename ?? "Choose rendered scene image"}</span><input type="file" accept="image/*" className="hidden" onChange={(event) => readSceneFile(index, event.target.files?.[0])} /></label><Button disabled={!hasActiveProject || !selectedFile || uploadScene.isPending} onClick={() => hasActiveProject && selectedFile && uploadScene.mutate({ projectId: activeProjectId, kind: "lifestyle", ...selectedFile, sceneIndex: index, sceneTitle: scene.title, prompt: scene.prompt })} className="rounded-xl bg-[#d8bb84] text-[#26342b]"><Upload className="mr-2" size={15} /> {uploadScene.isPending ? "Uploading" : "Upload scene"}</Button></div>{sceneAssets.length > 0 && <div className="mt-5 grid gap-3 sm:grid-cols-2">{sceneAssets.map((asset) => <div key={asset.id} className="overflow-hidden rounded-xl border border-[#e4dbce] bg-white"><img src={asset.url} alt={scene.title + " uploaded render"} className="aspect-[4/3] w-full object-cover" /><div className="flex items-center justify-between p-3"><span className="font-mono text-[9px] uppercase tracking-[.12em] text-[#84796b]">{asset.status}</span>{asset.status === "approved" || asset.status === "published" ? <span className="flex items-center gap-2 font-mono text-[9px] uppercase text-[#304c3b]"><Check size={15} /> Selected for lookbook</span> : asset.status === "review" && user?.role === "admin" ? <span className="flex gap-3 font-mono text-[9px] uppercase"><button onClick={() => reviewScene.mutate({ assetId: asset.id, status: "approved" })} className="text-[#304c3b]">Approve</button><button onClick={() => reviewScene.mutate({ assetId: asset.id, status: "rejected", rejectionReason: "Needs a new scene variation." })} className="text-[#9b4e48]">Reject</button></span> : <span className="font-mono text-[9px] uppercase text-[#a47c45]">{asset.status}</span>}</div></div>)}</div>}</CardContent></div></Card>})}</div><div className="mt-8 rounded-2xl border border-[#d9d0c3] bg-[#fbfaf7] p-6"><p className="eyebrow">Scene quality gate</p><div className="mt-4 grid gap-3 sm:grid-cols-3">{["Every beat has a distinct spatial context", "Every prompt preserves the approved wreath anchor", "Every returned render is tied to a scene index"].map((item) => <div key={item} className="flex gap-3 font-serif text-lg"><Check className="mt-1 shrink-0 text-[#5f8163]" size={16} />{item}</div>)}</div></div></section>}

{tab === "lookbook" && <section className="py-12"><div className="grid gap-8 lg:grid-cols-[1.15fr_.85fr]"><div className="rounded-3xl bg-[#d9c6a1] p-8 sm:p-14"><p className="eyebrow text-[#4a422f]">Stage 06 / finished story</p><h2 className="mt-5 max-w-3xl font-serif text-6xl font-light leading-none text-[#2f3128]">{currentLookbook?.title ?? "The lake house in July"}</h2><p className="mt-6 max-w-xl font-serif text-xl italic text-[#5e5748]">{latestStory?.body?.slice(0, 180) ?? "A keepsake built from the day that never quite ended."}</p>{approvedSceneAssets.length > 0 && <div className="mt-8 grid gap-3 sm:grid-cols-3">{approvedSceneAssets.map((asset) => <img key={asset.id} src={asset.url} alt="Approved lifestyle render selected for lookbook" className="aspect-[4/3] rounded-xl object-cover" />)}</div>}<div className="mt-10 grid gap-3 sm:grid-cols-3">{[["Story", latestStory ? `${Array.isArray(latestStory.beats) ? latestStory.beats.length : 0} cinematic beats` : "Awaiting Story Genesis"], ["Scenes", `${approvedSceneAssets.length} approved renders`], ["Anchor", `${blueprint.objects.length} placed stems`]].map(([label, value]) => <div key={label} className="border-t border-[#8f7e5d]/40 pt-3"><p className="font-mono text-[9px] uppercase tracking-[.16em] text-[#6d5b3e]">{label}</p><p className="mt-2 font-serif text-2xl text-[#2f3128]">{value}</p></div>)}</div><div className="mt-12 flex flex-wrap gap-3"><Link href="/lookbook"><Button className="rounded-full bg-[#304c3b]">Preview lookbook <ExternalLink className="ml-2" size={15} /></Button></Link><Button variant="outline" onClick={() => downloadText(`evercrafted-lookbook-${seed}.txt`, "The lake house in July\n\nA story-led lookbook assembled from an approved emotional direction, wreath anchor, and three placement scenes.")} className="rounded-full border-[#7b6949] bg-transparent text-[#394336]"><Download className="mr-2" size={15} /> Export review copy</Button></div></div><Card className="border-[#dfd3c1] bg-[#fbfaf7]"><CardContent className="p-8 sm:p-10"><p className="eyebrow">Assembly checklist</p><h3 className="mt-4 font-serif text-3xl font-light">Ready for a human review.</h3><div className="mt-8 space-y-4">{[["Story title and emotional territory", true], ["Wreath anchor and blueprint locked", true], ["Three placement-aware scenes", true], ["Gallery render selected", approvedSceneAssets.length > 0], ["Share link or publish state", false]].map(([label, complete]) => <div key={String(label)} className="flex items-start gap-3 border-b border-[#eee8df] pb-4"><span className={`mt-0.5 grid h-5 w-5 place-items-center rounded-full ${complete ? "bg-[#304c3b] text-white" : "border border-[#cdbd9e] text-[#a88d5e]"}`}>{complete ? <Check size={12} /> : <span className="h-1.5 w-1.5 rounded-full bg-[#cdbd9e]" />}</span><div><p className="font-serif text-lg">{label}</p><p className="mt-1 font-mono text-[9px] uppercase tracking-[.12em] text-[#9a8d7c]">{complete ? "complete" : "next review"}</p></div></div>)}</div><p className="mt-8 font-serif text-base italic leading-relaxed text-[#7c7163]">The lookbook is not a separate document at the end. It is the readable surface of the decisions made across the whole workspace.</p></CardContent></Card></div>
</section>}
</div></div></div></main>;
}
